#!/bin/bash
set -euo pipefail
umask 077
[[ $EUID -eq 0 ]] || { echo '请用 sudo bash'; exit 1; }
exec 9>/run/football-consolidated-install.lock
flock -n 9 || { echo '更新正在进行'; exit 1; }
for file in /opt/football/app/model.py /opt/football-web/injury_view.py /opt/football-injuries/collector.py /opt/football-injury-bridge/sync_injuries.py; do test -s "$file"; done
backup=/var/backups/football-consolidated-$(date +%Y%m%d-%H%M%S)
mkdir -p "$backup"
cp -a /opt/football/app "$backup/app"
cp -a /opt/football-web "$backup/web"
cp -a /opt/football-injuries "$backup/injuries"
cp -a /opt/football-injury-bridge "$backup/bridge"
[[ ! -f /opt/football/models/active.json ]] || cp -a /opt/football/models/active.json "$backup/active.json"
units='football-collect football-history football-train football-predict football-review football-injuries football-injury-view football-injury-bridge football-github-sync football-quality-audit football-model-status football-context football-consolidated'
for unit in $units; do
 if systemctl is-active --quiet "$unit.timer"; then echo "$unit.timer" >> "$backup/timers"; fi
 systemctl stop "$unit.timer" 2>/dev/null || true
done
resume() { if [[ -f "$backup/timers" ]]; then while read -r timer; do systemctl start "$timer" || true; done < "$backup/timers"; fi; }
rollback() {
 echo "安装验证失败，恢复代码。备份：$backup"
 cp -a "$backup/app/." /opt/football/app/
 cp -a "$backup/web/." /opt/football-web/
 cp -a "$backup/injuries/." /opt/football-injuries/
 cp -a "$backup/bridge/." /opt/football-injury-bridge/
 systemctl restart football-web.service || true
 resume
}
trap rollback ERR
echo '等待现有任务结束，避免打断写入。'
for unit in $units; do
 for attempt in $(seq 1 120); do
  state=$(systemctl show "$unit.service" -p ActiveState --value 2>/dev/null || true)
  [[ "$state" != activating && "$state" != active ]] && break
  if [[ $attempt -eq 120 ]]; then echo '任务仍运行，暂缓安装'; resume; exit 1; fi
  sleep 2
 done
done
python3 - <<'PATCH_PY'
import os,py_compile
from pathlib import Path
def save(p,s):
 st=p.stat();t=p.with_suffix('.new');t.write_text(s)
 if p.suffix=='.py':py_compile.compile(str(t),doraise=True)
 os.chmod(t,st.st_mode);os.chown(t,st.st_uid,st.st_gid);os.replace(t,p)
# Extend the installed collector in place so quota accounting and existing changes persist.
p=Path('/opt/football-injuries/collector.py');s=p.read_text()
if '# consolidated-form-v1' not in s:
 anchor="    report['local_requests_24h'] ="
 if s.count(anchor)!=1:raise RuntimeError('Collector version mismatch')
 block="""    # consolidated-form-v1
    try:
        from recent_form import collect as collect_recent_form
        report['recent_form']=collect_recent_form(db,request,now)
    except Exception as e:
        report['recent_form']={'state':'failed','error_type':type(e).__name__}
"""
 s=s.replace(anchor,block+anchor);save(p,s)
p=Path('/opt/football-web/web.py');s=p.read_text()
if '# consolidated-view-v1' not in s:
 anchor='  return result\n'
 if s.count(anchor)!=1:raise RuntimeError('Web version mismatch')
 s=s.replace(anchor,"  # consolidated-view-v1\n  from context_view import attach as attach_context\n  result['system_health']=attach_context(rows)\n"+anchor);save(p,s)
p=Path('/opt/football-injury-bridge/sync_injuries.py');s=p.read_text()
if '# consolidated-export-v1' not in s:
 s=s.replace("  out['matches'].append(item)","  # consolidated-export-v1\n  item['recent_form']=m.get('recent_form',{})\n  out['matches'].append(item)")
 s=s.replace(' return out\n'," out['system_health']=d.get('system_health',{})\n return out\n")
 if '# consolidated-export-v1' not in s:raise RuntimeError('Bridge version mismatch')
 save(p,s)
p=Path('/opt/football-web/app.js');s=p.read_text()
if '// consolidated-view-v1' not in s:
 anchor='for(const s of m.odds_sources)'
 if s.count(anchor)!=1:raise RuntimeError('UI version mismatch')
 block="""// consolidated-view-v1
const rb=node('div',undefined,'odds');rb.append(node('strong','独立来源近期赛果（未入模型）'));
const fl={ok:'已查询',not_queried:'等待额度轮转查询',empty_unverified:'暂无记录，覆盖未确认',stale:'数据较旧',post_kickoff_snapshot:'赛后查询，不作赛前依据',plan_or_season_restricted:'套餐或赛季权限不足',local_quota_limit:'已达本地请求上限',provider_quota_limit:'服务商额度不足'};
for(const side of ['home','away']){const f=m.recent_form?.[side]||{state:'not_queried'};rb.append(node('p',m[side]+' · '+(fl[f.state]||f.state)));if(f.at)rb.append(node('small','查询 '+format(f.at)));for(const g of f.matches||[])rb.append(node('small',format(g.kickoff)+' '+g.home+' '+g.home_goals+':'+g.away_goals+' '+g.away));}
rb.append(node('small','当前赛季近60天最多5场；未确认全部赛事覆盖。'));card.append(rb);
"""
 s=s.replace(anchor,block+anchor)
 health="""const hh=d.system_health||{};const hb=node('article',undefined,'match');hb.append(node('h3','系统运行检查'),node('p',hh.status==='ok'?'最近服务执行未见失败':hh.status==='needs_attention'?'有服务失败，请查看下方':'状态数据较旧或不可用'));
for(const [name,v] of Object.entries(hh.services||{}))if(v.Result!=='success')hb.append(node('p',name+' · '+v.Result,'warn'));
if(hh.training)hb.append(node('p','最近训练：'+hh.training.status+' · '+format(hh.training.at)));
$('matches').append(hb);
"""
 s=s.replace('for(const m of d.matches){',health+'for(const m of d.matches){');save(p,s)

PATCH_PY
install -d -m 700 /opt/football-consolidated
python3 - <<'FILES_PY'
from pathlib import Path
import base64,os,grp,py_compile
for name,data in {'/opt/football/app/model.py': '', '/opt/football-injuries/recent_form.py': '', '/opt/football-web/context_view.py': '', '/opt/football-web/publish_context.py': '', '/opt/football-consolidated/post_update.py': ''}.items():
 p=Path(name);t=p.with_suffix('.new');t.write_bytes(base64.b64decode(data));py_compile.compile(str(t),doraise=True)
 group='footballweb' if '/football-web/' in name else 'football' if '/football/app/' in name else 'root'
 t.chmod(0o640 if group!='root' else 0o600);os.chown(t,0,grp.getgrnam(group).gr_gid);os.replace(t,p)
FILES_PY
# The finite recheck already completed; stop its idle timer only when verified.
if python3 - <<'FINISHED'
import json,sys
try:d=json.load(open('/opt/football/reports/recent-repair.json'))
except (OSError,ValueError):sys.exit(1)
sys.exit(0 if d.get('complete') is True else 1)
FINISHED
then systemctl disable --now football-recent-repair.timer; fi
mkdir -p /etc/systemd/system/football-injuries.service.d
cat > /etc/systemd/system/football-injuries.service.d/context.conf <<'UNIT'
[Service]
TimeoutStartSec=420
UNIT
cat > /etc/systemd/system/football-context.service <<'UNIT'
[Unit]
Description=Publish private recent results and service health
[Service]
Type=oneshot
ExecStart=/usr/bin/python3 /opt/football-web/publish_context.py
TimeoutStartSec=90
NoNewPrivileges=true
ProtectSystem=strict
ProtectHome=true
ReadWritePaths=/opt/football-web
UNIT
cat > /etc/systemd/system/football-context.timer <<'UNIT'
[Timer]
OnBootSec=1min
OnUnitActiveSec=5min
[Install]
WantedBy=timers.target
UNIT
cat > /etc/systemd/system/football-consolidated.service <<'UNIT'
[Unit]
Description=Run model validation and private context update after installation
[Service]
Type=oneshot
ExecStart=/usr/bin/python3 /opt/football-consolidated/post_update.py
TimeoutStartSec=65min
UNIT
systemctl daemon-reload
systemctl start football-context.service
systemctl restart football-web.service
python3 - <<'CHECK_PY'
import json,time,urllib.request
c=json.load(open('/etc/football-web/access.json'));op=urllib.request.build_opener(urllib.request.ProxyHandler({}))
for i in range(8):
 try:
  req=urllib.request.Request('http://127.0.0.1:8787/ui-api/data',headers={'Authorization':'Bearer '+c['api_key']})
  with op.open(req,timeout=30) as r:d=json.load(r)
  assert 'system_health' in d and all('recent_form' in m for m in d['matches'])
  print('CONSOLIDATED_API_OK matches='+str(len(d['matches'])))
  break
 except Exception:
  if i==7:raise SystemExit('接口验证失败')
  time.sleep(1)
CHECK_PY
resume
systemctl enable --now football-context.timer
trap - ERR
systemctl start --no-block football-consolidated.service
echo 'CONSOLIDATED_INSTALLED：后台已提交近期赛果查询、模型训练验证及同步。'
echo '可以退出终端。安装成功不代表训练通过；新模型仅在验证优于基线与旧模型时替换。'
echo '近期赛果查询受套餐、覆盖和额度限制；天气、首发尚未接入。'
echo "原代码和原模型备份：$backup"
